"use client";
import Link from "next/link";
import { usePathname } from "next/navigation";

const ICONS: Record<string, string> = {
  today: "M8 2v4M16 2v4M3 10h18M5 5h14a2 2 0 0 1 2 2v12a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V7a2 2 0 0 1 2-2zM9 15l2 2 4-4",
  list: "M8 6h13M8 12h13M8 18h13M3 6h.01M3 12h.01M3 18h.01",
  calendar: "M3 5h18v16H3zM3 10h18M9 5v16M15 5v16",
  scan: "M4 8V5a1 1 0 0 1 1-1h3M16 4h3a1 1 0 0 1 1 1v3M20 16v3a1 1 0 0 1-1 1h-3M8 20H5a1 1 0 0 1-1-1v-3M8 8h3v3H8zM13 13h3v3h-3zM13 8h3M8 13v3",
  chat: "M21 12a8 8 0 0 1-11.6 7.1L4 20l1-4.6A8 8 0 1 1 21 12z",
  settings: "M4 7h10M18 7h2M4 17h4M12 17h8M14 4.5v5M8 14.5v5",
};

export function StaffNav({ slug, escalations, canSettings }: { slug: string; escalations: number; canSettings: boolean }) {
  const path = usePathname();
  const base = `/app/${slug}`;
  const items = [
    { href: base, label: "Today", icon: "today", exact: true },
    { href: `${base}/reservations`, label: "Reservations", icon: "list" },
    { href: `${base}/calendar`, label: "Calendar", icon: "calendar" },
    { href: `${base}/checkin`, label: "Check-in", icon: "scan" },
    { href: `${base}/conversations`, label: "Conversations", icon: "chat", badge: escalations },
    ...(canSettings ? [{ href: `${base}/settings`, label: "Settings", icon: "settings" }] : []),
  ];
  return (
    <nav aria-label="Main" className="fixed inset-x-0 bottom-0 z-20 flex border-t border-line bg-white/95 backdrop-blur md:static md:block md:w-56 md:shrink-0 md:border-0 md:bg-transparent md:py-4">
      {items.map((it) => {
        const active = it.exact ? path === it.href : path.startsWith(it.href);
        return (
          <Link key={it.href} href={it.href} aria-current={active ? "page" : undefined}
            className={`relative flex min-h-14 flex-1 flex-col items-center justify-center gap-0.5 text-[11px] font-semibold md:mb-1 md:min-h-11 md:flex-row md:justify-start md:gap-3 md:rounded-xl md:px-3 md:text-[15px] ${active ? "text-brand md:bg-white md:ring-1 md:ring-line" : "text-ink-soft hover:text-ink"}`}>
            <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true"><path d={ICONS[it.icon]} /></svg>
            <span className={it.label.length > 9 ? "max-md:hidden" : ""}>{it.label}</span>
            {it.label.length > 9 && <span className="md:hidden">{it.label === "Reservations" ? "List" : "Chats"}</span>}
            {it.badge ? <span className="absolute top-1.5 right-[22%] rounded-full bg-rose px-1.5 text-[11px] leading-5 font-bold text-white md:static md:ml-auto" aria-label={`${it.badge} waiting for staff`}>{it.badge}</span> : null}
          </Link>
        );
      })}
    </nav>
  );
}
