"use client";
import { api } from "./api";

export function SignOut() {
  return (
    <button type="button" className="rounded-lg px-2 py-1.5 text-sm font-semibold text-ink-soft hover:bg-paper"
      onClick={async () => { await api("/api/auth/logout", { method: "POST" }).catch(() => {}); window.location.assign("/"); }}>
      Sign out
    </button>
  );
}
