"use client";
import { useState } from "react";
import { useRouter } from "next/navigation";
import { api } from "./api";

/** The emergency stop for the assistant. One tap, takes effect on the customer's next message. */
export function AiSwitch({ businessId, enabled }: { businessId: string; enabled: boolean }) {
  const router = useRouter();
  const [on, setOn] = useState(enabled);
  const [busy, setBusy] = useState(false);
  async function toggle() {
    setBusy(true);
    const next = !on;
    try { await api(`/api/b/${businessId}/settings`, { method: "PATCH", body: { ai_enabled: next } }); setOn(next); router.refresh(); }
    catch (e) { window.alert((e as Error).message); }
    finally { setBusy(false); }
  }
  return (
    <button type="button" role="switch" aria-checked={on} disabled={busy} onClick={toggle} data-testid="ai-switch"
      className={`inline-flex min-h-10 items-center gap-2 rounded-full px-3 text-sm font-semibold ring-1 transition-colors ${on ? "bg-mint-soft text-[#087a5d] ring-mint/40" : "bg-amber-soft text-amber ring-amber/40"}`}>
      <span className={`relative h-5 w-9 rounded-full transition-colors ${on ? "bg-mint" : "bg-muted/50"}`} aria-hidden="true">
        <span className={`absolute top-0.5 size-4 rounded-full bg-white transition-all ${on ? "left-[18px]" : "left-0.5"}`} />
      </span>
      {on ? "Assistant on" : "Assistant paused"}
    </button>
  );
}
