"use client";
import { useEffect, useRef, useState } from "react";
import { useRouter } from "next/navigation";

/**
 * Keeps server-rendered staff pages current without reloading for nothing.
 * Primary: a live connection (server-sent events) that says "something changed".
 * Fallback: some networks, proxies and antivirus tools hold back live connections. Then the page
 * asks the server for a small fingerprint every 10 seconds and refreshes ONLY when it has changed.
 */
export function LiveRefresh({ businessId }: { businessId: string }) {
  const router = useRouter();
  const [state, setState] = useState<"connecting" | "live" | "checking">("connecting");
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null);

  useEffect(() => {
    let closed = false;
    let lastPulse: string | null = null;
    let gotEvent = false;
    const refresh = () => {
      if (timer.current) clearTimeout(timer.current);
      timer.current = setTimeout(() => router.refresh(), 250);
    };
    // Refresh only if the data fingerprint differs from the last one seen.
    const checkPulse = async () => {
      try {
        const res = await fetch(`/api/b/${businessId}/pulse`, { cache: "no-store" });
        if (!res.ok) return;
        const { v } = (await res.json()) as { v: string };
        if (lastPulse !== null && v !== lastPulse && !closed) refresh();
        lastPulse = v;
      } catch { /* offline: try again next time */ }
    };
    void checkPulse();

    const es = new EventSource(`/api/b/${businessId}/events`);
    es.addEventListener("hello", () => { gotEvent = true; setState("live"); });
    es.onmessage = () => { gotEvent = true; setState("live"); void checkPulse(); };
    es.onerror = () => { gotEvent = false; setState("checking"); };
    // If the connection opens but nothing ever arrives through it, something in between is
    // holding the stream back: fall back to checking.
    const settle = setTimeout(() => { if (!gotEvent && !closed) setState("checking"); }, 6000);

    const poll = setInterval(() => { if (!gotEvent && document.visibilityState === "visible") void checkPulse(); }, 10_000);
    const onVisible = () => { if (document.visibilityState === "visible") void checkPulse(); };
    document.addEventListener("visibilitychange", onVisible);
    return () => {
      closed = true; es.close(); clearInterval(poll); clearTimeout(settle);
      document.removeEventListener("visibilitychange", onVisible);
      if (timer.current) clearTimeout(timer.current);
    };
  }, [businessId, router]);

  const label = state === "live" ? "Live updates" : state === "checking" ? "Checking for changes every 10 seconds" : "Connecting";
  return (
    <span className="inline-flex items-center gap-1.5 text-[13px] text-muted" title={label} data-testid="live-state" data-state={state}>
      <span className={`size-2 rounded-full ${state === "connecting" ? "bg-amber" : "bg-mint"}`} aria-hidden="true" />
      <span className="hidden sm:inline">{state === "live" ? "Live" : state === "checking" ? "Auto-updating" : "Connecting"}</span>
    </span>
  );
}
